        dirty_wen_way0 = 1; 
        dirty_wdata_way0 = 0; 
        tag_array_wen_way0 = 1;
      end
      else begin
        valid_wen_way1 = 1; 
        dirty_wen_way1 = 1; 
        dirty_wdata_way1 = 0; 
        tag_array_wen_way1 = 1;
