    read_data_zero_mux_sel    = cs_read_data_zero_mux_sel;
    evict_addr_reg_en         = cs_evict_addr_reg_en;
    mem_req_addr_mux_sel      = cs_mem_req_addr_mux_sel;
    cacheresp_type            = cs_cacheresp_type;
    memreq_type               = cs_memreq_type;

