vc_EnResetReg#(32,0) cachereq_data_reg
(
  .clk    (clk),
  .reset  (reset),
  .en     (cachereq_en),
  .d      (proc2cache_reqstream_msg.data),
  .q      (cachereq_data_reg_out)
